import { useEffect, useMemo, useState } from 'react'
import { Activity, ArrowDownRight, ArrowRight, Box, ChevronDown, CircleHelp, Cloud, Command, Database, FileText, GitBranch, HardDrive, Layers3, LifeBuoy, Network, Plus, Search, Settings2, ShieldCheck, Sparkles, TerminalSquare, X } from 'lucide-react'
import { api, type ChangeEvent, type FieldResolution, type FieldAssertionView, type Impact, type Node, type NodeType, type Relation, type SyncPreview, type SyncRun, type SyncSource, type SourcePolicy, type MutationOperation, type ManualMutation, type MutationPlan } from './api'
import { GraphExplorer } from './GraphExplorer'

type View = 'overview' | 'all' | 'impact' | 'provisional' | 'sources' | 'sync' | 'explore'
const labels: Record<NodeType, string> = { Self: '我自己', Hardware: '硬件', Machine: '机器', SoftwareProject: '软件项目', SoftwareInstance: '部署实例', RunningPeriod: '运行周期', AccountCredential: '凭据元信息', Product: '产品', Document: '文档', Runbook: 'Runbook', WorkItem: '工作事项', Network:'网络', ProvisionalObject: '待分类' }
const navTypes: NodeType[] = ['Hardware', 'Machine', 'SoftwareProject', 'SoftwareInstance', 'AccountCredential', 'Document', 'WorkItem', 'Network']
const stableTypes: NodeType[] = ['Hardware', 'Machine', 'SoftwareProject', 'SoftwareInstance', 'RunningPeriod', 'AccountCredential', 'Product', 'Document', 'Runbook', 'WorkItem', 'Network']
const iconFor: Record<NodeType, typeof Box> = { Self: Sparkles, Hardware: HardDrive, Machine: TerminalSquare, SoftwareProject: GitBranch, SoftwareInstance: Layers3, RunningPeriod: Activity, AccountCredential: ShieldCheck, Product: Box, Document: FileText, Runbook: LifeBuoy, WorkItem: CircleHelp, Network:Network, ProvisionalObject: CircleHelp }
const typeColor: Record<NodeType, string> = { Self: 'violet', Hardware: 'blue', Machine: 'green', SoftwareProject: 'amber', SoftwareInstance: 'teal', RunningPeriod: 'teal', AccountCredential: 'rose', Product: 'blue', Document: 'slate', Runbook: 'amber', WorkItem: 'violet', Network:'teal', ProvisionalObject: 'rose' }
const evidenceLabel = { unknown: '未知', manual: '人工确认', document: '文档声明', observed: '现场核验', derived: '系统派生', imported: '导入' }
const certaintyLabel = { unknown: '未知', provisional: '暂定', confirmed: '已确认', disputed: '有冲突', stale: '已过期' }

async function previewAndConfirmMutation(mutation:ManualMutation):Promise<MutationPlan|null>{const plan=await api.previewMutation(mutation);const d=plan.delta;const changes=[['新增对象',d.addedNodes],['更新对象',d.updatedNodes],['删除对象',d.deletedNodes],['新增关系',d.addedRelations],['更新关系',d.updatedRelations],['删除关系',d.deletedRelations],['新增断言',d.addedAssertions],['删除断言',d.deletedAssertions]].filter(([,ids])=>(ids as string[]).length>0).map(([label,ids])=>`${label}：${(ids as string[]).join('、')}`).join('\n');if(!changes){window.alert('预览结果没有实际变更。');return null}return window.confirm(`即将应用以下变更：\n${changes}\n\n图谱版本：${plan.expectedRevision.slice(0,12)}…\n确认应用？`)?plan:null}

export function App() {
  const [nodes, setNodes] = useState<Node[]>([])
  const [relations, setRelations] = useState<Relation[]>([])
  const [impacts, setImpacts] = useState<Impact[]>([])
  const [provisionals, setProvisionals] = useState<Node[]>([])
  const [selected, setSelected] = useState<Node | null>(null)
  const [createOpen,setCreateOpen]=useState(false)
  const [path, setPath] = useState<{ nodes: Node[]; relations: Relation[] } | null>(null)
  const [assertions, setAssertions] = useState<FieldAssertionView[]>([])
  const [entityHistory, setEntityHistory] = useState<ChangeEvent[]>([])
  const [fieldResolutions, setFieldResolutions] = useState<FieldResolution[]>([])
  const [view, setView] = useState<View>('overview')
  const [filter, setFilter] = useState<NodeType | 'all'>('all')
  const [query, setQuery] = useState('')
  const [online, setOnline] = useState(false)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)
  const [reviewTarget, setReviewTarget] = useState<NodeType>('Machine')
  const [syncSources, setSyncSources] = useState<SyncSource[]>([])
  const [syncHistory, setSyncHistory] = useState<SyncRun[]>([])
  const [selectedSource, setSelectedSource] = useState('')

  const refresh = async () => {
    const [nodeResult, relationResult, impactResult, provisionalResult] = await Promise.all([api.nodes(), api.relations(), api.impact(), api.provisionals()])
setNodes(nodeResult.items); setRelations(relationResult.items); setImpacts(impactResult.items); setProvisionals(provisionalResult.items); setSelected(current=>current?nodeResult.items.find(node=>node.id===current.id)??null:null); setOnline(true); setError('')
  }
  useEffect(() => {
    let active = true
    Promise.all([api.nodes(), api.relations(), api.impact(), api.provisionals(), api.health()])
      .then(([nodeResult, relationResult, impactResult, provisionalResult]) => { if (active) { setNodes(nodeResult.items); setRelations(relationResult.items); setImpacts(impactResult.items); setProvisionals(provisionalResult.items); setOnline(true); setError('') } })
      .catch((cause: unknown) => { if (active) { setOnline(false); setError(cause instanceof Error ? cause.message : '无法连接 API') } })
      .finally(() => { if (active) setLoading(false) })
    return () => { active = false }
  }, [])

  useEffect(() => { if (selected?.candidateType) setReviewTarget(selected.candidateType) }, [selected])
  useEffect(() => {
    if (view !== 'sources') return
    let active=true
    api.syncSources().then(result=>{ if(active) { setSyncSources(result.items); if(result.items.length && !selectedSource) setSelectedSource(result.items[0].source) } }).catch(cause=>{ if(active) setError(cause instanceof Error?cause.message:'来源历史读取失败') })
    return ()=>{active=false}
  },[view,selectedSource])
  useEffect(() => {
    if(view!=='sources' || !selectedSource) { setSyncHistory([]); return }
    let active=true
    api.syncHistory(selectedSource).then(result=>{if(active)setSyncHistory(result.items)}).catch(cause=>{if(active)setError(cause instanceof Error?cause.message:'同步历史读取失败')})
    return ()=>{active=false}
  },[view,selectedSource])

  const editTypeDetails=async(node:Node)=>{const keys:Partial<Record<NodeType,string>>={Hardware:'hardware',Machine:'machine',SoftwareProject:'softwareProject',SoftwareInstance:'softwareInstance',AccountCredential:'accountCredential',Product:'product',Document:'document',Runbook:'runbook',WorkItem:'workItem',Network:'network'};const key=keys[node.type];if(!key)return;const current=(node as unknown as Record<string,unknown>)[key]??{};const raw=window.prompt(`编辑 ${labels[node.type]} 类型详情 JSON（不含秘密或正文）`,JSON.stringify(current,null,2));if(raw===null)return;let details:unknown;try{details=JSON.parse(raw);if(details!==null&&(typeof details!=='object'||Array.isArray(details)))throw new Error('详情必须是 JSON 对象')}catch(cause){setError(cause instanceof Error?cause.message:'详情 JSON 无效');return};let token=sessionStorage.getItem('mkw-write-token')||window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN');if(!token)return;sessionStorage.setItem('mkw-write-token',token);try{const updated={...node,[key]:details} as Node;const mutation:ManualMutation={kind:'updateNode',id:node.id,node:updated};const plan=await previewAndConfirmMutation(mutation);if(!plan)return;await api.applyMutation(mutation,plan,token);setSelected(updated);await refresh()}catch(cause){sessionStorage.removeItem('mkw-write-token');setError(cause instanceof Error?cause.message:'类型详情更新失败')}}

  const resolveFieldAssertion = async (assertion:FieldAssertionView) => {
    const rationaleReference=window.prompt(`为 ${assertion.fieldPath} 选择此断言。请输入安全的决策/依据引用（不要输入秘密或原始敏感值）：`)
    if(!rationaleReference?.trim())return
    let token=sessionStorage.getItem('mkw-write-token');if(!token){token=window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN（仅保存在当前浏览器会话）');if(!token)return;sessionStorage.setItem('mkw-write-token',token)}
    try{const resolution=await api.createFieldResolution({nodeId:assertion.nodeId,fieldPath:assertion.fieldPath,selectedAssertionIds:[assertion.id],rationaleReference},token);setFieldResolutions(old=>[resolution,...old.filter(item=>item.id!==resolution.id)]);setAssertions(old=>old.map(item=>item.fieldPath===assertion.fieldPath?{...item,resolved:true,selected:item.id===assertion.id,resolutionId:resolution.id}:item));setError('字段裁决已追加；原始断言仍完整保留。')}
    catch(cause){sessionStorage.removeItem('mkw-write-token');setError(cause instanceof Error?cause.message:'字段裁决失败')}
  }

  const reviewAction = async (node: Node, action: 'classify' | 'reject') => {
    let token = sessionStorage.getItem('mkw-write-token')
    if (!token) {
      token = window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN（仅保存在当前浏览器会话）')
      if (!token) return
      sessionStorage.setItem('mkw-write-token', token)
    }
    try {
      if (action === 'classify') {
        const certainty = window.prompt('确定性：unknown / provisional / confirmed / disputed / stale', node.certainty || 'confirmed')
        if (certainty === null) return
        const source = window.prompt('证据来源（可留空以保留原来源）', '')
        if (source === null) return
        const reference = window.prompt('证据引用（可留空；仅填安全引用，不填秘密或正文）', '')
        if (reference === null) return
        await api.reviewProvisional(node.id, reviewTarget, token, { certainty: certainty as import('./api').Certainty, source: source.trim() || undefined, reference: reference.trim() || undefined })
      } else await api.rejectProvisional(node.id, token)
      await refresh(); setSelected(null)
    } catch (cause) {
      sessionStorage.removeItem('mkw-write-token')
      setError(cause instanceof Error ? cause.message : '审查操作失败')
    }
  }

  useEffect(() => {
    if (!selected) { setPath(null); setAssertions([]); setEntityHistory([]); setFieldResolutions([]); return }
    let active = true
    api.path(selected.id).then(result => { if (active) setPath(result) }).catch(() => { if (active) setPath(null) })
    api.assertions(selected.id).then(result=>{if(active)setAssertions(result.items)}).catch(()=>{if(active)setAssertions([])})
    api.entityHistory('node',selected.id).then(result=>{if(active)setEntityHistory(result.items)}).catch(()=>{if(active)setEntityHistory([])})
    api.fieldResolutions(selected.id).then(result=>{if(active)setFieldResolutions(result.items)}).catch(()=>{if(active)setFieldResolutions([])})
    return () => { active = false }
  }, [selected])

  const self = nodes.find(node => node.type === 'Self')
  const provisionalIds = useMemo(() => new Set(provisionals.map(node => node.id)), [provisionals])
  const visibleNodes = useMemo(() => nodes.filter(node => {
    const matchesFilter = filter === 'all' || node.type === filter
    const matchesQuery = `${node.name} ${node.type} ${node.id}`.toLowerCase().includes(query.toLowerCase())
    const matchesView = view !== 'provisional' || provisionalIds.has(node.id)
    return node.type !== 'Self' && matchesFilter && matchesQuery && matchesView
  }), [nodes, filter, query, view, provisionalIds])
  const recent = [...nodes].filter(node => node.lastConfirmed).sort((a, b) => (b.lastConfirmed ?? '').localeCompare(a.lastConfirmed ?? '')).slice(0, 3)
  const counts = new Map<NodeType, number>()
  nodes.forEach(node => counts.set(node.type, (counts.get(node.type) ?? 0) + 1))
  const impactIds = new Set(impacts.map(item => item.node.id))
  const focus = (node: Node) => { setSelected(node) }

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><Network size={19} strokeWidth={2.3} /></div><span>my<span className="brand-light">known</span>world</span><button className="workspace-switch" aria-label="切换工作区"><ChevronDown size={14} /></button></div>
      <div className="workspace"><div className="workspace-avatar">M</div><div><strong>我的世界</strong><small>个人认知图谱</small></div><span className={`status-dot ${online ? 'on' : ''}`} title={online ? 'API 在线' : 'API 离线'} /></div>
      <div className="side-label">工作区</div>
      <button className={`nav-item ${view === 'overview' ? 'active' : ''}`} onClick={() => { setView('overview'); setFilter('all') }}><Layers3 size={17} /><span>总览</span><span className="nav-kbd">⌘ 1</span></button>
      <button className={`nav-item ${view === 'all' ? 'active' : ''}`} onClick={() => { setView('all'); setFilter('all') }}><Database size={17} /><span>全部对象</span><span className="nav-count">{Math.max(0, nodes.length - 1)}</span></button>
      <button className={`nav-item ${view === 'impact' ? 'active' : ''}`} onClick={() => { setView('impact'); setFilter('all') }}><Activity size={17} /><span>影响范围</span></button>
      <button className={`nav-item ${view === 'explore' ? 'active' : ''}`} onClick={() => setView('explore')}><Network size={17} /><span>关系图探索</span></button>
      <button className={`nav-item ${view === 'provisional' ? 'active' : ''}`} onClick={() => { setView('provisional'); setFilter('all') }}><CircleHelp size={17} /><span>待审查队列</span><span className="nav-count">{provisionals.length}</span></button>
      <button className={`nav-item ${view === 'sync' ? 'active' : ''}`} onClick={() => setView('sync')}><ArrowDownRight size={17} /><span>批量同步</span></button>
      <button className={`nav-item ${view === 'sources' ? 'active' : ''}`} onClick={() => setView('sources')}><Database size={17} /><span>来源与同步历史</span></button>
      <div className="side-label category-label">分类 <button aria-label="分类设置"><Settings2 size={14} /></button></div>
      {navTypes.map(type => { return <button key={type} className={`nav-item sub-item ${filter === type ? 'active' : ''}`} onClick={() => { setFilter(type); setView('all') }}><span className={`type-dot ${typeColor[type]}`} /><span>{labels[type]}</span><span className="nav-count">{counts.get(type) ?? 0}</span></button> })}
      <div className="sidebar-bottom"><div className="storage-card"><div className="storage-top"><span className="storage-icon"><Cloud size={15} /></span><span>{online ? '数据连接正常' : '等待 API 连接'}</span></div><p>{online ? '图谱连接正常' : '检查本地 API 服务'}</p><div className="storage-track"><span style={{ width: online ? '72%' : '8%' }} /></div><small>{online ? 'PostgreSQL / API' : '离线模式'}</small></div><button className="nav-item"><CircleHelp size={17} /><span>帮助与文档</span></button><div className="profile-row"><div className="profile-avatar">M</div><div><strong>Me</strong><small>本地空间</small></div><button aria-label="个人设置"><Settings2 size={16} /></button></div></div>
    </aside>

    <main className="main-area">
      <header className="topbar"><div className="breadcrumbs"><span>我的世界</span><span className="crumb-slash">/</span><strong>{view === 'overview' ? '总览' : view === 'impact' ? '影响范围' : view === 'provisional' ? '待分类对象' : view === 'sources' ? '来源与同步历史' : view === 'sync' ? '批量同步' : view === 'explore' ? '关系图探索' : filter === 'all' ? '全部对象' : labels[filter]}</strong></div><div className="top-actions"><div className={`connection ${online ? 'connected' : ''}`}><span />{online ? '已连接' : '未连接'}</div><div className="top-divider" /><button className="icon-button" aria-label="搜索"><Command size={16} /></button><div className="top-avatar">M</div></div></header>
      <div className="content">
        <section className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" />个人认知图谱 <span className="eyebrow-dot">·</span> <span>只记录我已知的世界</span></div><h1>{view === 'overview' ? <>你的世界，<span>一目了然。</span></> : view === 'impact' ? <>关系与<span>影响路径。</span></> : view === 'provisional' ? <>先收集，再<span>慢慢确认。</span></> : view === 'sources' ? <>每次同步，<span>都有记录。</span></> : view === 'sync' ? <>批量导入，<span>先预览再应用。</span></> : view === 'explore' ? <>从任意对象，<span>追踪关系。</span></> : <>所有对象，<span>清晰连接。</span></>}</h1><p className="subtitle">从对象、关系与来源出发，理解哪些事物与你有关。</p></div><button className="add-button" onClick={() => setCreateOpen(true)}><Plus size={17} /> 新建对象</button></section>

        {error && <div className="alert"><CircleHelp size={16} /><span>{error}</span><button onClick={() => setError('')} aria-label="关闭"><X size={15} /></button></div>}
        {loading ? <div className="loading-state"><span className="spinner" /> 正在读取你的图谱…</div> : <>
          {view === 'overview' && <>
            <section className="summary-grid">
              <SummaryCard label="已知对象" value={Math.max(0, nodes.length - 1)} hint="不含 Self 锚点" icon={<Box size={17} />} tone="lilac" />
              <SummaryCard label="影响范围" value={impacts.length} hint="排除仅知晓关系" icon={<Activity size={17} />} tone="mint" />
              <SummaryCard label="待分类" value={provisionals.length} hint="等待后续审查" icon={<CircleHelp size={17} />} tone="peach" />
              <SummaryCard label="已维护对象" value={impacts.filter(item => item.relationPath.some(relation => relation.predicate === 'maintains')).length} hint="从 Self 出发可追溯" icon={<ShieldCheck size={17} />} tone="bluewash" />
            </section>
            <section className="panel self-relations"><div className="panel-head"><div><div className="panel-title">Self 关系视角</div><div className="panel-sub">owns、maintains 与 knowsAbout 各自独立，不相互推导</div></div></div><div className="self-relation-groups">{([{predicate:'owns',label:'我拥有 / 控制',tone:'blue'},{predicate:'maintains',label:'我负责维护',tone:'green'},{predicate:'uses',label:'我使用',tone:'teal'},{predicate:'canOperate',label:'我可受限操作',tone:'rose'},{predicate:'knowsAbout',label:'我仅知晓',tone:'amber'}] as const).map(group => { const targets=relations.filter(relation=>relation.from===self?.id && relation.predicate===group.predicate).map(relation=>nodes.find(node=>node.id===relation.to)).filter((node):node is Node=>Boolean(node)); return <div className="self-relation-group" key={group.predicate}><div className={`relation-group-title ${group.tone}`}><span />{group.label}<small>{targets.length}</small></div>{targets.length ? targets.map(node=><button className="relation-target" key={node.id} onClick={()=>focus(node)}><TypeIcon type={node.type}/><span>{node.name}</span><ArrowRight size={13}/></button>) : <div className="relation-empty">暂无对象</div>}</div> })}</div></section>
            <section className="overview-grid">
              <div className="panel graph-panel"><div className="panel-head"><div><div className="panel-title">关系图谱</div><div className="panel-sub">从 Self 出发的已确认影响关系</div></div><button className="text-action" onClick={() => setView('impact')}>查看影响 <ArrowRight size={14} /></button></div><GraphPreview self={self} impacts={impacts} onSelect={focus} /></div>
              <div className="panel pulse-panel"><div className="panel-head"><div><div className="panel-title">图谱状态</div><div className="panel-sub">当前认知概况</div></div><span className="tiny-live"><span /> 已查询</span></div><div className="pulse-score"><div className="score-number">{nodes.length ? '—' : '0'}<span> / 100</span></div><div className="score-label">图谱完整度暂不评分</div></div><div className="pulse-divider" /><div className="pulse-row"><span className="pulse-bullet green" />所有对象可追溯至 Self<span className="pulse-check">✓</span></div><div className="pulse-row"><span className="pulse-bullet blue" />影响分析排除 knowsAbout<span className="pulse-check">✓</span></div><div className="pulse-row"><span className="pulse-bullet amber" />来源与核验时间持续完善<span className="pulse-muted">进行中</span></div></div>
            </section>
            <section className="panel objects-panel"><div className="panel-head object-head"><div><div className="panel-title">最近确认的对象</div><div className="panel-sub">按最近核验时间排序</div></div><button className="text-action" onClick={() => { setView('all'); setFilter('all') }}>全部对象 <ArrowRight size={14} /></button></div><ObjectTable nodes={recent} impacts={impactIds} selected={selected} onSelect={focus} /></section>
          </>}
          {view === 'sources' && <SyncHistoryPanel sources={syncSources} history={syncHistory} selectedSource={selectedSource} onSelect={setSelectedSource} />}
          {view === 'sync' && <><SourcePolicyPanel/><SyncBatchPanel onApplied={refresh} /><OperationHistoryPanel onUndone={refresh}/></>}
          {view === 'explore' && <GraphExplorer nodes={nodes} onSelect={focus} />}
          {view !== 'overview' && view !== 'sources' && view !== 'sync' && view !== 'explore' && <section className="panel objects-panel listing-panel"><div className="list-toolbar"><div><div className="panel-title">{view === 'impact' ? '影响传播路径' : view === 'provisional' ? '待确认对象' : filter === 'all' ? '对象目录' : labels[filter]}</div><div className="panel-sub">{view === 'impact' ? '仅沿明确的业务与运行关系传播' : '对象关系与状态可独立追溯'}</div></div><label className="search-box"><Search size={15} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索对象名称或类型…" /></label></div>{view === 'impact' ? <ImpactList impacts={impacts.filter(item => `${item.node.name} ${labels[item.node.type]}`.toLowerCase().includes(query.toLowerCase()))} onSelect={focus} /> : <ObjectTable nodes={visibleNodes} impacts={impactIds} selected={selected} onSelect={focus} />}</section>}
        </>}
        <footer className="page-footer"><span>MyKnownWorld</span><span>准确表达已知，不臆测未知。</span><span>模型版本 1.0</span></footer>
      </div>
    </main>

    {createOpen&&<NodeCreateDialog nodes={nodes} onClose={()=>setCreateOpen(false)} onCreated={async()=>{setCreateOpen(false);await refresh()}}/>}
    {selected && <><button className="drawer-scrim" onClick={() => setSelected(null)} aria-label="关闭详情" /><aside className="detail-drawer"><div className="drawer-head"><span className="drawer-kicker">对象详情</span><button className="icon-button" onClick={() => setSelected(null)} aria-label="关闭"><X size={18} /></button></div><div className="detail-icon-wrap"><TypeIcon type={selected.type} /></div><div className="detail-type">{labels[selected.type]}</div><h2>{selected.name}</h2><div className="detail-id">{selected.id}</div><div className="detail-chips">{selected.lifecycle && <span className="chip lifecycle"><span />{selected.lifecycle}</span>}<span className="chip">模型 v{selected.modelVersion}</span><button className="text-button" onClick={()=>{const name=window.prompt('修改对象名称',selected.name);if(name?.trim())void (async()=>{let token=sessionStorage.getItem('mkw-write-token')||window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN');if(!token)return;sessionStorage.setItem('mkw-write-token',token);try{const updated={...selected,name:name.trim()};const mutation:ManualMutation={kind:'updateNode',id:selected.id,node:updated};const plan=await previewAndConfirmMutation(mutation);if(!plan)return;await api.applyMutation(mutation,plan,token);setSelected(updated);await refresh()}catch(cause){setError(cause instanceof Error?cause.message:'更新失败')}})()}}>编辑名称</button>{selected.type!=='Self'&&selected.type!=='RunningPeriod'&&selected.type!=='ProvisionalObject'&&<button className="text-button" onClick={()=>void editTypeDetails(selected)}>编辑类型详情</button>}</div>{selected.type === 'ProvisionalObject' && selected.reviewStatus !== 'rejected' && <div className="review-panel"><strong>待审查暂存对象</strong><p>候选类型：{selected.candidateType ? labels[selected.candidateType] : '尚未建议'}</p>{selected.reviewQuestions?.map(question => <small key={question}>• {question}</small>)}<label>确认类型<select value={reviewTarget} onChange={event => setReviewTarget(event.target.value as NodeType)}>{stableTypes.map(type => <option value={type} key={type}>{labels[type]}</option>)}</select></label><div className="review-actions"><button onClick={() => void reviewAction(selected, 'classify')}>转为明确对象</button><button className="reject" onClick={() => void reviewAction(selected, 'reject')}>保留并拒绝分类</button></div><small>写入操作需配置 MYKNOWNWORLD_WRITE_TOKEN；令牌仅保存在当前浏览器会话。</small></div>}<div className="drawer-section"><div className="section-heading">与 Self 的关系路径 <span>{path?.relations.length ?? 0} 条关系</span></div>{path ? path.relations.length ? <div className="path-stack">{path.nodes.map((node, index) => <div className="path-step" key={node.id}><div className={`path-icon ${typeColor[node.type]}`}><TypeIcon type={node.type} /></div><div className="path-copy"><strong>{node.name}</strong><small>{labels[node.type]}</small></div>{index < path.nodes.length - 1 && <div className="path-edge"><span>{path.relations[index]?.predicate}</span><ArrowDownRight size={14} /></div>}</div>)}</div> : <div className="empty-note">Self 节点本身是图谱锚点。</div> : <div className="loading-line"><span className="spinner small" /> 正在查询关系路径</div>}</div><div className="drawer-section"><div className="section-heading">已知信息</div><div className="fact-row"><span>生命周期</span><strong>{selected.lifecycle || '未记录'}</strong></div><div className="fact-row"><span>信息来源</span><strong>{selected.source === 'unspecified' ? '未说明' : selected.source}</strong></div><div className="fact-row"><span>证据类型 / 确定性</span><strong>{evidenceLabel[selected.evidenceKind]} / {certaintyLabel[selected.certainty]}</strong></div><div className="fact-row"><span>最近核验</span><strong>{selected.lastConfirmed ? new Date(selected.lastConfirmed).toLocaleDateString('zh-CN') : '尚未核验'}</strong></div><div className="fact-row"><span>节点标识</span><strong className="mono">{selected.id}</strong></div></div><ModelDetailsPanel node={selected}/><RelationMaintenancePanel node={selected} nodes={nodes} relations={relations} onChanged={refresh}/>{assertions.length>0 && <div className="drawer-section"><div className="section-heading">字段级来源断言 <span>{assertions.length} 条</span></div>{assertions.map(assertion=><div className="assertion-row" key={assertion.id}><strong>{assertion.fieldPath}{assertion.selected?' · 当前已选证据':assertion.resolved?' · 与当前裁决不同':' · 未裁决'}</strong><span>{assertion.source} · {evidenceLabel[assertion.evidenceKind]} · {certaintyLabel[assertion.certainty]}</span><small>{assertion.reference||'无外部引用'} · {new Date(assertion.assertedAt).toLocaleString('zh-CN')}</small>{!assertion.selected&&<button className="text-button" onClick={()=>void resolveFieldAssertion(assertion)}>追加裁决并选择此断言</button>}</div>)}</div>}{selected.type === 'RunningPeriod' && <div className="drawer-section"><div className="section-heading">运行周期记录</div><div className="fact-row"><span>开始 / 结束</span><strong>{selected.startedAt ? new Date(selected.startedAt).toLocaleString('zh-CN') : '未知'} / {selected.endedAt ? new Date(selected.endedAt).toLocaleString('zh-CN') : '仍在运行或未知'}</strong></div><div className="fact-row"><span>部署版本</span><strong>{selected.deployedVersion || '未知'}</strong></div><div className="fact-row"><span>最近验证</span><strong>{selected.verificationAt ? new Date(selected.verificationAt).toLocaleString('zh-CN') : '未验证'}</strong></div><div className="fact-row"><span>验证结果</span><strong>{selected.verificationResult || '未知'}</strong></div><div className="fact-row"><span>证据引用</span><strong className="mono">{selected.evidenceRef || '未记录'}</strong></div></div>}{entityHistory.length>0&&<div className="drawer-section"><div className="section-heading">对象变更历史<span>{entityHistory.length} 条</span></div>{entityHistory.map(event=><div className="assertion-row" key={event.id}><strong>{({created:'建立',updated:'更新',stale:'来源缺失/过期',deleted:'显式删除'} as Record<string,string>)[event.action]??event.action}</strong><span>{event.source} · {new Date(event.recordedAt).toLocaleString('zh-CN')}</span><small>{event.runId?`同步批次 #${event.runId}`:'人工操作'}</small></div>)}</div>}{fieldResolutions.length>0&&<div className="drawer-section"><div className="section-heading">字段分歧裁决记录<span>{fieldResolutions.length} 条</span></div>{fieldResolutions.map(item=><div className="assertion-row" key={item.id}><strong>{item.fieldPath}</strong><span>选定断言：{item.selectedAssertionIds.join('、')}</span><small>{item.rationaleReference} · {new Date(item.recordedAt).toLocaleString('zh-CN')}</small></div>)}</div>}<div className="drawer-note"><ShieldCheck size={16} /><span>路径展示已记录的关系；可达不代表当前运行或状态正常。</span></div></aside></>}
  </div>
}

function NodeCreateDialog({nodes,onClose,onCreated}:{nodes:Node[];onClose:()=>void;onCreated:()=>Promise<void>}){
 const types=stableTypes;const [type,setType]=useState<NodeType>('Machine');const [id,setID]=useState('');const [name,setName]=useState('');const [lifecycle,setLifecycle]=useState('');const [details,setDetails]=useState('{}');const [predicate,setPredicate]=useState('knowsAbout');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false)
 const detailKey:Partial<Record<NodeType,string>>={Hardware:'hardware',Machine:'machine',SoftwareProject:'softwareProject',SoftwareInstance:'softwareInstance',AccountCredential:'accountCredential',Product:'product',Document:'document',Runbook:'runbook',WorkItem:'workItem',Network:'network'}
 const save=async()=>{if(!id.trim()||!name.trim()){setMessage('对象 ID 和名称必填');return};let detail:unknown;try{detail=JSON.parse(details)}catch{setMessage('类型详情必须是有效 JSON');return};const self=nodes.find(item=>item.type==='Self');if(!self){setMessage('当前图谱缺少 Self 锚点');return};let token=sessionStorage.getItem('mkw-write-token')||window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN（仅保存在当前浏览器会话）');if(!token)return;sessionStorage.setItem('mkw-write-token',token)
 const node={id:id.trim(),type,name:name.trim(),lifecycle,modelVersion:1,source:'manual:ui',evidenceKind:'manual',certainty:'confirmed',...(detailKey[type]?{[detailKey[type]!]:detail}:{})} as Node;const relation:Relation={id:`onboard-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,from:self.id,predicate,to:node.id,source:'manual:ui',evidenceKind:'manual',certainty:'confirmed',recordedAt:new Date().toISOString()};setBusy(true);try{const mutation:ManualMutation={kind:'createNode',node,relation};const plan=await previewAndConfirmMutation(mutation);if(!plan)return;await api.applyMutation(mutation,plan,token);await onCreated()}catch(cause){sessionStorage.removeItem('mkw-write-token');setMessage(cause instanceof Error?cause.message:'创建失败')}finally{setBusy(false)}}
 return <div className="modal-scrim" role="presentation"><section className="panel create-node-dialog" role="dialog" aria-modal="true" aria-label="创建图谱对象"><div className="panel-head"><div><div className="panel-title">创建明确对象</div><div className="panel-sub">对象发布时必须显式选择与 Self 的关系；不自动推断拥有或维护。</div></div><button className="icon-button" onClick={onClose} aria-label="关闭">×</button></div><div className="explore-controls"><label>对象类型<select value={type} onChange={event=>{setType(event.target.value as NodeType);setDetails('{}')}}>{types.map(value=><option key={value}>{value}</option>)}</select></label><label>Self 关系<select value={predicate} onChange={event=>setPredicate(event.target.value)}>{['knowsAbout','owns','maintains','uses','canOperate'].map(value=><option key={value}>{value}</option>)}</select></label></div><div className="explore-controls"><label>稳定 ID<input value={id} onChange={event=>setID(event.target.value)} placeholder="例如 machine-lab"/></label><label>名称<input value={name} onChange={event=>setName(event.target.value)} placeholder="对象名称"/></label><label>生命周期<input value={lifecycle} onChange={event=>setLifecycle(event.target.value)} placeholder="未知也可留空"/></label></div>{detailKey[type]&&<label className="create-details-label">{type} 类型详情 JSON<textarea value={details} onChange={event=>setDetails(event.target.value)} spellCheck={false}/></label>}<small>不要在类型详情中填写密码、令牌、私钥、文档正文或低熵敏感值。缺少详情不会阻止录入。</small>{message&&<p className="sync-conflict">{message}</p>}<div className="sync-batch-actions"><button onClick={()=>void save()} disabled={busy}>{busy?'创建中…':'创建并发布'}</button><button className="text-button" onClick={onClose}>取消</button></div></section></div>
}

function RelationMaintenancePanel({node,nodes,relations,onChanged}: {node:Node;nodes:Node[];relations:Relation[];onChanged:()=>Promise<void>}){
 const [predicate,setPredicate]=useState('uses');const [target,setTarget]=useState('');const [message,setMessage]=useState('');const touching=relations.filter(item=>item.from===node.id||item.to===node.id);const candidates=nodes.filter(item=>item.id!==node.id)
 const token=()=>{let value=sessionStorage.getItem('mkw-write-token');if(!value){value=window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN（仅保存在当前浏览器会话）')||'';if(value)sessionStorage.setItem('mkw-write-token',value)}return value}
 const add=async()=>{const auth=token();if(!auth||!target)return;const relation:Relation={id:`manual-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,from:node.id,predicate,to:target,source:'manual:ui',evidenceKind:'manual',certainty:'confirmed',recordedAt:new Date().toISOString()};try{const mutation:ManualMutation={kind:'addRelation',relation};const plan=await previewAndConfirmMutation(mutation);if(!plan)return;await api.applyMutation(mutation,plan,auth);setMessage('关系已添加');await onChanged()}catch(cause){setMessage(cause instanceof Error?cause.message:'关系添加失败')}}
 const remove=async(id:string)=>{if(!window.confirm(`显式删除关系 ${id}？如果会造成对象与 Self 断连，服务器将拒绝。`))return;const auth=token();if(!auth)return;try{const mutation:ManualMutation={kind:'deleteRelation',id};const plan=await previewAndConfirmMutation(mutation);if(!plan)return;await api.applyMutation(mutation,plan,auth);setMessage('关系已删除');await onChanged()}catch(cause){setMessage(cause instanceof Error?cause.message:'关系删除失败')}}
 return <div className="drawer-section"><div className="section-heading">关系维护 <span>{touching.length} 条</span></div>{touching.map(item=><div className="assertion-row" key={item.id}><strong>{item.from===node.id?'→':'←'} {item.predicate} · {item.from===node.id?item.to:item.from}</strong><small>{item.source} · {item.certainty}</small><button className="text-button" onClick={()=>void remove(item.id)}>显式删除</button></div>)}<div className="explore-controls"><label>关系谓词<select value={predicate} onChange={event=>setPredicate(event.target.value)}>{['owns','maintains','uses','canOperate','knowsAbout','hosts','routesThrough','providesAccessTo','implementedFrom','hasRunningPeriod','hasCredential','documents','appliesTo','targets','supersedes','dependsOn'].map(value=><option key={value}>{value}</option>)}</select></label><label>目标节点<select value={target} onChange={event=>setTarget(event.target.value)}><option value="">选择对象</option>{candidates.map(item=><option key={item.id} value={item.id}>{item.name} · {labels[item.type]}</option>)}</select></label></div><button className="text-button" disabled={!target} onClick={()=>void add()}>从当前对象添加出向关系</button>{message&&<small>{message}</small>}<small>写入需配置令牌；关系端点和 Self 连通性由服务器校验。</small></div>
}

function ModelDetailsPanel({node}:{node:Node}) {
 const list=(values?:string[])=>values?.join(', ')||'—'
 const rows:[string,string][]=[]
 if(node.hardware){const d=node.hardware;rows.push(['设备类别 / 型号',[d.category,d.model].filter(Boolean).join(' / ')||'—'],['位置 / 状态',[d.location,d.status].filter(Boolean).join(' / ')||'—'],['硬件规格',Object.entries(d.specifications??{}).map(([k,v])=>`${k}: ${v}`).join(' · ')||'—'],['访问说明引用',d.accessReference||'—'],['维护说明引用',d.maintenanceReference||'—'])}
 if(node.machine){const d=node.machine;rows.push(['Hostname / OS',[d.hostname,d.os].filter(Boolean).join(' / ')||'—'],['IP / 网络',[list(d.ips),d.network].filter(x=>x!=='—').join(' / ')||'—'],['机器状态 / 责任边界',[d.status,d.responsibilityBoundary].filter(Boolean).join(' / ')||'—'],['访问方式 / 前提',[d.accessMethod,list(d.accessPrerequisites)].filter(x=>x&&x!=='—').join(' / ')||'—'],['允许操作',list(d.allowedOperations)],['禁止操作',list(d.forbiddenOperations)],['自管资源',(d.resources??[]).map(r=>`${r.kind}: ${r.name}${r.port?` :${r.port}`:''}`).join(' · ')||'—'],['最近核验',d.lastVerified?new Date(d.lastVerified).toLocaleString('zh-CN'):'—'])}
 if(node.softwareProject){const d=node.softwareProject;rows.push(['用途 / 形态',[d.purpose,d.form].filter(Boolean).join(' / ')||'—'],['语言',list(d.languages)],['远程仓库 / 上游',[d.remoteRepository,d.upstream].filter(Boolean).join(' · ')||'—'],['维护 / 推荐版本',[d.maintenanceState,d.recommendedVersion].filter(Boolean).join(' / ')||'—'],['继任项目',d.successorId||'—'])}
 if(node.softwareInstance){const d=node.softwareInstance;rows.push(['产品 / 部署方式',[d.productName,d.deploymentMethod].filter(Boolean).join(' / ')||'—'],['部署路径 / 身份',[d.deploymentPath,d.runtimeIdentity].filter(Boolean).join(' / ')||'—'],['端点',(d.endpoints??[]).map(e=>`${e.kind} ${e.address}${e.port?`:${e.port}`:''}`).join(' · ')||'—'],['配置引用',list(d.configurationReferences)],['部署 / 运行 / 维护',[d.deploymentState,d.operationalState,d.maintenanceState].filter(Boolean).join(' / ')||'—'],['最近验证',[d.verificationResult,d.verifiedAt].filter(Boolean).join(' · ')||'—'])}
 if(node.accountCredential){const d=node.accountCredential;rows.push(['账号 / 类型',[d.account,d.credentialType].filter(Boolean).join(' / ')||'—'],['用途 / 范围',[d.purpose,d.scope].filter(Boolean).join(' / ')||'—'],['保管位置引用',d.accessReference||'—'],['状态 / 轮换',[d.status,d.rotationAt].filter(Boolean).join(' / ')||'—'])}
 if(node.product){const d=node.product;rows.push(['用途',d.purpose||'—'],['共性配置 / Runbook',[d.commonConfigurationReference,d.runbookReference].filter(Boolean).join(' · ')||'—'])}
 if(node.document){const d=node.document;rows.push(['职责 / 权威位置',[d.role,d.authoritativeReference].filter(Boolean).join(' / ')||'—'],['当前有效',d.effective?'是':'未知'],['最近核验 / 替代',[d.lastVerified,d.supersededBy].filter(Boolean).join(' / ')||'—'])}
 if(node.runbook){const d=node.runbook;rows.push(['触发 / 前置条件',[d.trigger,list(d.preconditions)].filter(x=>x&&x!=='—').join(' / ')||'—'],['步骤 / 停止 / 回退引用',[d.stepsReference,d.stopConditionReference,d.rollbackReference].filter(Boolean).join(' · ')||'—'],['验证方式 / 状态',[d.verificationMethod,d.executableStatus].filter(Boolean).join(' / ')||'—'],['需要人工批准',d.approvalRequired?'是':'否'])}
 if(node.workItem){const d=node.workItem;rows.push(['事项类型 / 状态',[d.kind,d.status].filter(Boolean).join(' / ')||'—'],['理由 / 决策证据引用',[d.rationaleReference,d.decisionEvidenceReference].filter(Boolean).join(' · ')||'—'])}
 if(node.network){const d=node.network;rows.push(['网络类型 / 状态',[d.kind,d.status].filter(Boolean).join(' / ')||'—'],['CIDR',d.cidrs?.join('、')||'—'],['网关 / VPN 引用',[d.gatewayReference,d.vpnReference].filter(Boolean).join(' · ')||'—'],['访问位置',d.accessLocations?.join('、')||'—'])}
 if(!rows.length)return null
 return <div className="drawer-section"><div className="section-heading">类型专属信息</div>{rows.map(([label,value])=><div className="fact-row" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>
}

function OperationHistoryPanel({onUndone}:{onUndone:()=>Promise<void>}){const [items,setItems]=useState<MutationOperation[]>([]);const [message,setMessage]=useState('');const load=()=>api.mutationOperations().then(result=>setItems(result.items)).catch(cause=>setMessage(cause instanceof Error?cause.message:'操作历史不可用'));useEffect(()=>{void load()},[]);const undo=async(item:MutationOperation)=>{if(!item.reversible||!window.confirm(`撤回操作 #${item.id}（${item.action}）？仅当图谱未在此操作后变化时允许撤回。`))return;let token=sessionStorage.getItem('mkw-write-token')||window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN');if(!token)return;sessionStorage.setItem('mkw-write-token',token);try{await api.undoOperation(item.id,token);setMessage(`已撤回操作 #${item.id}`);await onUndone();await load()}catch(cause){sessionStorage.removeItem('mkw-write-token');setMessage(cause instanceof Error?cause.message:'撤回失败')}};return <section className="panel sync-history-panel"><div className="panel-head"><div><div className="panel-title">可恢复的手动操作</div><div className="panel-sub">只可撤回当前图谱仍与该操作结果完全一致的变更；仅支持逆序安全回滚。</div></div></div>{items.map(item=><article className="sync-run" key={item.id}><div className="sync-run-head"><strong>操作 #{item.id} · {item.action}</strong><time>{new Date(item.recordedAt).toLocaleString('zh-CN')}</time></div><div className="sync-batch-actions"><button disabled={!item.reversible} onClick={()=>void undo(item)}>{item.reversible?'撤回此操作':'图谱已变化 / 已撤回'}</button></div></article>)}{!items.length&&<small>暂无可撤回的手动操作。{message&&` ${message}`}</small>}{items.length>0&&message&&<p className="sync-conflict">{message}</p>}</section>}

function SourcePolicyPanel(){
 const [items,setItems]=useState<SourcePolicy[]>([]);const [text,setText]=useState('{\n  "source": "inventory",\n  "priority": 50,\n  "allowedNodeTypes": ["Machine"],\n  "allowedPredicates": ["knowsAbout", "hosts"],\n  "allowedFieldPaths": ["machine.hostname", "machine.os", "machine.ips"]\n}');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false)
 const refresh=()=>api.sourcePolicies().then(result=>setItems(result.items)).catch(cause=>setMessage(cause instanceof Error?cause.message:'来源策略不可用'))
 useEffect(()=>{void refresh()},[])
 const save=async()=>{let policy:SourcePolicy;try{policy=JSON.parse(text) as SourcePolicy}catch{setMessage('JSON 格式无效');return};const token=sessionStorage.getItem('mkw-write-token')||window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN');if(!token)return;sessionStorage.setItem('mkw-write-token',token);setBusy(true);try{await api.saveSourcePolicy(policy,token);setMessage(`已保存来源策略：${policy.source}`);await refresh()}catch(cause){sessionStorage.removeItem('mkw-write-token');setMessage(cause instanceof Error?cause.message:'保存失败')}finally{setBusy(false)}}
 return <section className="panel sync-batch-panel"><div className="panel-head"><div><div className="panel-title">来源范围与优先级</div><div className="panel-sub">精确 allow-list；优先级仅作提示，不自动裁决事实。未配置的来源保持旧行为。</div></div></div><div className="sync-run-tags">{items.map(item=><button key={item.source} onClick={()=>setText(JSON.stringify(item,null,2))}>{item.source} · P{item.priority} · {item.allowedNodeTypes.length} 类对象</button>)}</div><textarea value={text} onChange={event=>setText(event.target.value)} spellCheck={false} aria-label="来源策略 JSON"/><div className="sync-batch-actions"><button onClick={()=>void save()} disabled={busy}>保存/更新策略</button><span>{busy?'保存中…':message}</span></div><small>策略适用于批次内全部节点类型、关系谓词及字段断言。被拒绝的批次不会部分写入。建议按来源职责配置最小范围。</small></section>
}

function SyncBatchPanel({onApplied}:{onApplied:()=>Promise<void>}) {
  const [text,setText]=useState(''); const [preview,setPreview]=useState<SyncPreview|null>(null); const [busy,setBusy]=useState(false); const [message,setMessage]=useState('')
  const previewBatch=async()=>{setBusy(true);setMessage('');try{const batch=JSON.parse(text) as {source?:string};const result=await api.previewBatch(batch);setPreview(result);setMessage(`预览完成：${result.source}`)}catch(cause){setPreview(null);setMessage(cause instanceof Error?cause.message:'预览失败')}finally{setBusy(false)}}
  const applyBatch=async()=>{if(!preview||preview.conflicts.length||!preview.source)return;let batch:unknown;try{batch=JSON.parse(text)}catch{setMessage('JSON 格式无效');return};if(!window.confirm(`将批次应用到数据源「${preview.source}」。缺失记录只会标记 stale，不会删除。继续？`))return;let token=sessionStorage.getItem('mkw-write-token');if(!token){token=window.prompt('请输入 MYKNOWNWORLD_WRITE_TOKEN（仅保存在当前浏览器会话）');if(!token)return;sessionStorage.setItem('mkw-write-token',token)}setBusy(true);setMessage('');try{const result=await api.applyBatch(batch,token);setPreview(result.preview);setMessage('批次已原子应用');await onApplied()}catch(cause){sessionStorage.removeItem('mkw-write-token');setMessage(cause instanceof Error?cause.message:'批次应用失败')}finally{setBusy(false)}}
  return <section className="panel sync-batch-panel"><div className="panel-head"><div><div className="panel-title">导入来源批次</div><div className="panel-sub">提交一个完整来源快照；先预览差异，再以确认令牌原子应用。最大 8 MiB。</div></div></div><textarea value={text} onChange={event=>{setText(event.target.value);setPreview(null)}} placeholder={'粘贴 SourceBatch JSON，例如 {"source":"my-source","nodes":[],"relations":[]}'} spellCheck={false}/><div className="sync-batch-actions"><button onClick={()=>void previewBatch()} disabled={busy||!text.trim()}>预览差异</button><button onClick={()=>void applyBatch()} disabled={busy||!preview||preview.conflicts.length>0}>确认并应用</button><span>{busy?'处理中…':message}</span></div>{preview&&<div className="sync-preview-result"><strong>{preview.source} · {preview.sourceHash}</strong><div className="sync-run-tags"><span>新增对象 {preview.addedNodes.length}</span><span>更新对象 {preview.updatedNodes.length}</span><span>缺失标记 {preview.missingNodes.length}</span><span>新增关系 {preview.addedRelations.length}</span><span>更新关系 {preview.updatedRelations.length}</span><span>字段断言 {preview.addedAssertions.length+preview.updatedAssertions.length}</span><span>冲突 {preview.conflicts.length}</span></div>{preview.conflicts.map(conflict=><p className="sync-conflict" key={conflict}>{conflict}</p>)}{preview.valueConflicts?.map(conflict=><p className="sync-conflict" key={`${conflict.nodeId}:${conflict.fieldPath}`}>字段值有跨来源分歧：{conflict.nodeId} · {conflict.fieldPath}（来源：{conflict.sources.join('、')}；断言：{conflict.assertionIds.join('、')}）。未显示摘要或原值，不自动裁决。</p>)}<small>不会自动删除缺失数据。重命名需要显式或已保存的身份映射。</small></div>}</section>
}

function SyncHistoryPanel({sources,history,selectedSource,onSelect}:{sources:SyncSource[];history:SyncRun[];selectedSource:string;onSelect:(source:string)=>void}) {
  if(!sources.length) return <section className="panel"><div className="empty-state"><div className="empty-art"><Database size={22}/></div><strong>还没有已应用的数据源</strong><span>批次预览不会写入历史；应用批次后，这里会显示来源、哈希和变更报告。</span></div></section>
  return <section className="panel sync-history-panel"><div className="panel-head"><div><div className="panel-title">来源目录与同步历史</div><div className="panel-sub">只记录来源标识、哈希、解析器版本和变更 ID；不保存导入正文。</div></div><select value={selectedSource} onChange={event=>onSelect(event.target.value)}>{sources.map(source=><option key={source.source} value={source.source}>{source.source}</option>)}</select></div><div className="source-summary">{sources.filter(source=>source.source===selectedSource).map(source=><div key={source.source}><span>最近应用</span><strong>{new Date(source.appliedAt).toLocaleString('zh-CN')}</strong><span>解析器</span><strong>{source.parserVersion||'未提供'}</strong><span>SHA-256</span><code>{source.sourceHash}</code></div>)}</div><div className="sync-run-list">{history.map(run=><article className="sync-run" key={run.id}><div className="sync-run-head"><strong>运行 #{run.id}{run.undone?' · 已撤回':''}</strong><time>{new Date(run.appliedAt).toLocaleString('zh-CN')}</time></div><div className="sync-run-tags"><span>新增对象 {run.preview.addedNodes?.length??0}</span><span>更新对象 {run.preview.updatedNodes?.length??0}</span><span>缺失标记 {run.preview.missingNodes?.length??0}</span><span>新增关系 {run.preview.addedRelations?.length??0}</span><span>冲突 {run.preview.conflicts?.length??0}</span></div><code>{run.sourceHash}</code></article>)}</div></section>
}

function SummaryCard({ label, value, hint, icon, tone }:  { label: string; value: number; hint: string; icon: React.ReactNode; tone: string }) { return <div className="summary-card"><div className={`summary-icon ${tone}`}>{icon}</div><div className="summary-label">{label}</div><div className="summary-value">{value}<span className="summary-unit"> 个</span></div><div className="summary-hint">{hint}</div></div> }
function TypeIcon({ type }: { type: NodeType }) { const Icon = iconFor[type]; return <Icon size={17} strokeWidth={1.8} /> }

function ObjectTable({ nodes, impacts, selected, onSelect }: { nodes: Node[]; impacts: Set<string>; selected: Node | null; onSelect: (node: Node) => void }) {
  if (!nodes.length) return <div className="empty-state"><div className="empty-art"><Layers3 size={22} /></div><strong>还没有匹配的对象</strong><span>图谱只展示已明确建模的对象，不会根据名称推测关系。</span></div>
  return <div className="table-wrap"><table><thead><tr><th>对象</th><th>类型</th><th>生命周期</th><th>确定性</th><th>影响范围</th><th>最近核验</th><th /></tr></thead><tbody>{nodes.map(node => <tr key={node.id} className={selected?.id === node.id ? 'selected-row' : ''} onClick={() => onSelect(node)}><td><div className="object-cell"><div className={`type-icon ${typeColor[node.type]}`}><TypeIcon type={node.type} /></div><div><strong>{node.name}</strong><small>{node.id}</small></div></div></td><td><span className="type-label">{labels[node.type]}</span></td><td>{node.lifecycle ? <span className="lifecycle-cell"><span />{node.lifecycle}</span> : <span className="muted">未记录</span>}</td><td><span className={`certainty ${node.certainty}`}>{certaintyLabel[node.certainty]}</span></td><td>{impacts.has(node.id) ? <span className="impact-label"><Activity size={13} /> 可传播</span> : <span className="muted">—</span>}</td><td>{node.lastConfirmed ? new Date(node.lastConfirmed).toLocaleDateString('zh-CN') : <span className="muted">未核验</span>}</td><td><ArrowRight size={15} className="row-arrow" /></td></tr>)}</tbody></table></div>
}

function ImpactList({ impacts, onSelect }: { impacts: Impact[]; onSelect: (node: Node) => void }) {
  if (!impacts.length) return <div className="empty-state"><div className="empty-art"><Activity size={22} /></div><strong>暂无可传播的影响路径</strong><span>仅知晓关系不会进入影响分析。维护、拥有和明确运行关系才会参与传播。</span></div>
  return <div className="impact-list">{impacts.map(item => <button className="impact-row" key={item.node.id} onClick={() => onSelect(item.node)}><div className={`type-icon ${typeColor[item.node.type]}`}><TypeIcon type={item.node.type} /></div><div className="impact-main"><strong>{item.node.name}</strong><span>{item.relationPath.map(relation => relation.predicate).join('  →  ')}</span></div><span className="impact-kind">{labels[item.node.type]}</span><ArrowRight size={15} className="row-arrow" /></button>)}</div>
}

function GraphPreview({ self, impacts, onSelect }: { self?: Node; impacts: Impact[]; onSelect: (node: Node) => void }) {
  const items = impacts.slice(0, 4)
  if (!self || !items.length) return <div className="graph-empty"><div className="graph-empty-circle"><Network size={23} /></div><strong>关系图谱正在等待明确的业务关系</strong><span>仅知晓（knowsAbout）关系不会进入影响传播。</span><button className="text-action" onClick={() => onSelect(self ?? { id: 'self', name: 'Self', type: 'Self', source: 'unspecified', evidenceKind: 'unknown', certainty: 'unknown', modelVersion: 1 })}>查看 Self 锚点 <ArrowRight size={14} /></button></div>
  return <div className="graph-canvas"><div className="graph-grid" /><svg className="graph-lines" viewBox="0 0 600 244" preserveAspectRatio="none" aria-hidden="true">{items.map((_, index) => <path key={index} d={`M 300 120 C ${200 + index * 15} ${120 - 45 + index * 22}, 145 ${46 + index * 47}, 100 ${45 + index * 47}`} />)}</svg><button className="graph-node self-node" onClick={() => onSelect(self)}><span className="graph-node-mark"><Sparkles size={18} /></span><strong>Self</strong><small>认知锚点</small></button>{items.map((item, index) => <button key={item.node.id} className={`graph-node connected-node node-${index}`} onClick={() => onSelect(item.node)}><span className={`graph-node-mark ${typeColor[item.node.type]}`}><TypeIcon type={item.node.type} /></span><strong>{item.node.name}</strong><small>{item.relationPath.at(-1)?.predicate ?? labels[item.node.type]}</small></button>)}<div className="graph-legend"><span><i className="legend-dot self" />Self</span><span><i className="legend-dot relation" />明确关系</span></div></div>
}
